<script lang="ts">
 import {tick} from 'svelte';import {model,setDraft,submit,demanderPicker,detacherPiece} from '../model';import Icon from './Icon.svelte';import RequestCard from './RequestCard.svelte';import AttachmentChip from './AttachmentChip.svelte';import {renderMarkdown} from '../markdown';
 let log:HTMLDivElement;let selected=0;
 $: commands=$model.draft.startsWith('/')?$model.commands.filter(c=>c.cmd.toLowerCase().startsWith($model.draft.toLowerCase())).slice(0,6):[];
 $: count=$model.messages.length;
 $: if(count&&log){const target=log,near=target.scrollHeight-target.scrollTop-target.clientHeight<80;void tick().then(()=>{if(near&&target.isConnected)target.scrollTop=target.scrollHeight;});}
 function toolIcon(name:string):string{
  const n=name.toLowerCase();
  if(/search|web|site|url|navigat|browse|fetch|arxiv|deep/.test(n))return 'globe';
  if(/file|read|write|edit|diff/.test(n))return 'file';
  return 'bolt';
 }
 function choose(value:string){setDraft(value.split(' ')[0]+' ');selected=0;}
 function key(event:KeyboardEvent){if(event.isComposing)return;if(commands.length&&['ArrowDown','ArrowUp','Tab'].includes(event.key)){event.preventDefault();if(event.key==='Tab')choose(commands[Math.min(selected,commands.length-1)].cmd);else selected=(selected+(event.key==='ArrowDown'?1:-1)+commands.length)%commands.length;}else if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();submit();}}
</script>
<div class="chat-body"><div class="log" bind:this={log} role="log" aria-live="polite">{#if !$model.messages.length}<div class="empty"><Icon name="chat"/><p>Aucun message</p></div>{/if}{#each $model.messages as message (message.id)}{#if message.who==='outil'}<div class="tool-event"><span class="tool-mark"><Icon name={toolIcon(message.text)}/></span><b>{message.text}</b>{#if message.detail}<span class="tool-detail">{message.detail}</span>{/if}</div>{:else}<article class:mine={message.who==='toi'}><div class="author">{message.who}</div><div class="md">{@html renderMarkdown(message.text)}</div></article>{/if}{/each}</div><RequestCard/>{#if ['thinking','working'].includes($model.state)&&!$model.requests.length}<div class="typing"><i></i><i></i><i></i><span>{$model.state==='working'?'Axon travaille':'Axon réfléchit'}</span></div>{/if}{#if commands.length}<div class="commands" aria-label="Suggestions de commandes">{#each commands as command,i}<button class:selected={i===selected} onclick={()=>choose(command.cmd)}><b>{command.cmd}</b><span>{command.desc}</span></button>{/each}</div>{/if}{#if $model.attachments.length}<div class="attachments" aria-label="Pièces jointes">{#each $model.attachments as a (a.nom)}<AttachmentChip nom={a.nom} statut={a.statut} message={a.message} taille={a.taille} onRemove={()=>detacherPiece(a.nom)}/>{/each}</div>{/if}<form onsubmit={e=>{e.preventDefault();submit();}}><button type="button" class="attach" title="Joindre un fichier" aria-label="Joindre un fichier" disabled={!$model.connected||$model.demo} onclick={demanderPicker}><Icon name="paperclip"/></button><textarea rows="2" value={$model.draft} oninput={e=>{selected=0;setDraft(e.currentTarget.value);}} onkeydown={key} placeholder={$model.requests.length?'Ta réponse…':'Demande à Axon…'} aria-label="Message à Axon" title="Entrée pour envoyer, Maj+Entrée pour une nouvelle ligne" disabled={$model.busy}></textarea><button class="send" title="Envoyer" aria-label="Envoyer" disabled={!$model.draft.trim()||(!$model.connected&&!$model.demo)||$model.busy}><Icon name="send"/></button></form></div>
<style>.chat-body{display:flex;flex-direction:column;height:100%;gap:9px;min-height:0}.log{flex:1;min-height:0;overflow:auto;padding:0 2px 4px}.empty{height:100%;min-height:80px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#858893;gap:8px}.empty p{font-size:11px}article{padding:9px 0;line-height:1.65;font-size:12px;animation:msgIn 200ms var(--spring-soft) both}@keyframes msgIn{0%{opacity:0;transform:translateY(6px)}100%{opacity:1;transform:translateY(0)}}.author{font-size:9px;color:#797d88;margin-bottom:3px}.md{user-select:text}.md :global(p){white-space:pre-wrap;overflow-wrap:anywhere;margin:0 0 7px}.md :global(p:last-child){margin-bottom:0}.md :global(h1),.md :global(h2),.md :global(h3){font-size:12.5px;font-weight:600;color:#e7e8ee;margin:10px 0 5px}.md :global(h1:first-child),.md :global(h2:first-child),.md :global(h3:first-child){margin-top:0}.md :global(strong){color:#eceef4;font-weight:600}.md :global(em){font-style:italic}.md :global(code){font:11px var(--mono);background:#ffffff0d;padding:1px 5px;border-radius:4px;overflow-wrap:anywhere}.md :global(pre){background:#0006;border:1px solid #ffffff0f;padding:8px 10px;border-radius:8px;overflow:auto;margin:6px 0}.md :global(pre code){background:none;padding:0;white-space:pre}.md :global(ul),.md :global(ol){margin:4px 0 7px;padding-left:18px}.md :global(li){margin:2px 0}.md :global(blockquote){margin:6px 0;padding:2px 0 2px 10px;border-left:2px solid #ffaf0045;color:var(--muted)}.md :global(a){color:var(--accent);text-decoration:underline;text-underline-offset:2px}.md :global(.table-wrap){margin:6px 0;overflow-x:auto;border:1px solid #ffffff0f;border-radius:8px}.md :global(table){border-collapse:collapse;width:100%;font-size:10.5px}.md :global(th),.md :global(td){padding:6px 9px;text-align:left;border-bottom:1px solid #ffffff0a;white-space:nowrap}.md :global(th:last-child),.md :global(td:last-child){white-space:normal}.md :global(th){background:#ffffff06;color:#c7c9d4;font-weight:600}.md :global(tr:last-child td){border-bottom:none}.mine{margin-left:12%;background:linear-gradient(120deg,#ffffff0a,#ffffff03);border:1px solid #ffffff0b;border-radius:18px;padding:9px 12px}.tool-event{display:flex;align-items:center;gap:8px;padding:5px 2px;font-size:10px;color:var(--muted);animation:toolIn 180ms var(--spring-soft) both}.tool-event b{font-weight:500;color:#9fa3af;flex:none}.tool-event .tool-detail{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--faint)}.tool-mark{width:18px;height:18px;border-radius:6px;display:grid;place-items:center;background:#ffffff08;color:#8a8ea0;flex:none}.tool-mark :global(.icon){width:10px;height:10px}@keyframes toolIn{0%{opacity:0;transform:translateX(-3px)}100%{opacity:1;transform:translateX(0)}}.attachments{display:flex;flex-wrap:wrap;gap:6px;flex:none}form{display:flex;gap:8px;align-items:flex-end;padding:11px;border:1px solid #ffffff13;border-radius:22px;background:#ffffff05;flex:none}form:focus-within{border-color:#ffaf0040}.attach{width:28px;height:28px;flex:none;border-radius:50%;display:grid;place-items:center;color:var(--muted);margin-bottom:1px}.attach:hover{background:#ffffff0a;color:var(--text)}.attach:disabled{opacity:.4}.attach :global(.icon){width:13px;height:13px}textarea{width:100%;min-width:0;border:0;background:transparent;color:var(--text);font:12px/1.5 var(--font);resize:none;outline:none;max-height:100px;appearance:none;-webkit-appearance:none;border-radius:10px}textarea:focus,textarea:focus-visible{outline:none;box-shadow:none}.send{width:30px;height:30px;flex:none;border-radius:50%;display:grid;place-items:center;background:linear-gradient(135deg,#ffdaa0,#ffaf35);color:#241700}.typing{display:flex;align-items:center;gap:3px;color:var(--muted);font-size:10px;height:15px;flex:none}.typing span{margin-left:5px}.typing i{width:3px;height:3px;border-radius:50%;background:#a7aab4;animation:pulse 1.2s ease-in-out infinite}.typing i:nth-child(2){animation-delay:.15s}.typing i:nth-child(3){animation-delay:.3s}@keyframes pulse{50%{opacity:.35}}.commands{flex:none;max-height:112px;overflow:auto;border:1px solid #ffffff12;border-radius:17px;padding:6px;background:#242332e8;backdrop-filter:blur(16px)}.commands button{display:flex;gap:10px;padding:6px 8px;width:100%;text-align:left;font-size:10px;border-radius:5px}.commands b{color:#e1b867;font:10px var(--mono)}.commands span{color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.commands button.selected,.commands button:hover{background:#ffffff08}</style>
